using System.IO.Abstractions;
using System.IO.Abstractions.TestingHelpers;
using System.Reflection;

namespace UnitTests.Views;

public class FileDialogIconTests
{
    [Theory]
    [InlineData ("[F] ", "[F] file.txt")]
    [InlineData ("", "file.txt")]
    public void Table_UsesCustomIconText (string icon, string expected)
    {
        MockFileSystem fileSystem = new ();
        fileSystem.AddFile ("/test-dir/file.txt", new MockFileData ("contents"));
        using FileDialog dialog = new TestableFileDialog (fileSystem);
        dialog.Style.IconProvider = new TextIconProvider (icon);
        dialog.PushState (fileSystem.DirectoryInfo.New ("/test-dir"), false);

        FileDialogTableSource table = new (dialog, dialog.State, dialog.Style, 0, true);
        int row = Array.FindIndex (dialog.State!.Children, entry => entry.Name == "file.txt");

        Assert.True (row >= 0);
        Assert.Equal (expected, table [row, 0]);
        Assert.Equal ("..", table [0, 0]);
    }

    [Fact]
    public void Tree_UsesCustomIconTextAndExpansionState ()
    {
        MockFileSystem fileSystem = new ();
        fileSystem.AddFile ("/test-dir/sub-dir/file.txt", new MockFileData ("contents"));
        fileSystem.AddDirectory ("/test-dir/sub-dir/nested-dir");
        IDirectoryInfo root = fileSystem.DirectoryInfo.New ("/test-dir");
        using FileDialog dialog = new TestableFileDialog (fileSystem);
        dialog.Style.IconProvider = new TextIconProvider ("[F] ");
        dialog.Style.TreeRootGetter = () => new () { { root, "Test root" } };
        dialog.BeginInit ();
        dialog.EndInit ();

        FieldInfo? treeField = typeof (FileDialog).GetField ("_treeView", BindingFlags.Instance | BindingFlags.NonPublic);
        Assert.NotNull (treeField);
        TreeView<IFileSystemInfo> tree = Assert.IsType<TreeView<IFileSystemInfo>> (treeField.GetValue (dialog));
        tree.Expand (root);
        IDirectoryInfo directory = Assert.IsAssignableFrom<IDirectoryInfo> (Assert.Single (tree.GetChildren (root)));

        Assert.Equal ("[+] sub-dir", tree.AspectGetter (directory));
        tree.Expand (directory);
        Assert.Equal ("[-] sub-dir", tree.AspectGetter (directory));
    }

    private sealed class TextIconProvider (string fileIcon) : FileSystemIconProvider
    {
        public override string GetIconWithOptionalSpace (IFileSystemInfo? fileSystemInfo)
        {
            if (fileSystemInfo is not IDirectoryInfo directory)
            {
                return fileIcon;
            }

            return IsOpenGetter (directory) ? "[-] " : "[+] ";
        }
    }

    private sealed class TestableFileDialog (IFileSystem fileSystem) : FileDialog (fileSystem);
